import sys
from pathlib import Path

REPO_ROOT = Path(__file__).resolve().parent.parent


def get_documented_entries(doc_path: Path) -> set[str]:
    if not doc_path.exists():
        return set()
    entries = set()
    for line in doc_path.read_text().splitlines():
        if line.startswith("### "):
            header = line[4:].split(" — ")[0]
            for part in header.split("/"):
                entries.add(part.strip())
    return entries


def audit_file(path: Path, documented: set[str]) -> list[str]:
    try:
        tree = ast.parse(path.read_text())
    except Exception as e:
        return [f"parse error in {path}: {e}"]

    missing = []
    for node in tree.body:
        if isinstance(node, ast.FunctionDef):
            if node.name not in documented:
                missing.append(f"{path.relative_to(REPO_ROOT)}: function '{node.name}'")
        elif isinstance(node, ast.ClassDef):
            for subnode in node.body:
                if isinstance(subnode, ast.FunctionDef):
                    class_method = f"{node.name}.{subnode.name}"
                    if class_method not in documented:
                        missing.append(
                            f"{path.relative_to(REPO_ROOT)}: method '{class_method}'"
                        )
    return missing


def main() -> int:
    doc_path = REPO_ROOT / "docs" / "functions.md"
